package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
class ExchangeSyncTest {
    static JdbcTemplate db;ExchangeSync sync;ExchangeService exchange;PlatformExchangeService source;OrderRepository repo;
    @BeforeAll static void init(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));db=OrderTestDatabase.jdbc(url);}
    @BeforeEach void seed(){for(String t:Arrays.asList("oms_exchange_sync_item","oms_exchange_sync","oms_exchange_config"))db.update("DELETE FROM "+t);repo=new OrderRepository();ReflectionTestUtils.setField(repo,"jdbc",db);sync=new ExchangeSync();ReflectionTestUtils.setField(sync,"repository",repo);exchange=mock(ExchangeService.class);ReflectionTestUtils.setField(sync,"exchanges",exchange);when(exchange.capability("VERIFY",1)).thenReturn(map("read_enabled",1,"can_query",true));source=mock(PlatformExchangeService.class);ReflectionTestUtils.setField(sync,"platformExchanges",source);when(source.ingest(eq("VERIFY"),eq(1L),anyMap(),anyString())).thenAnswer(i->map("id",Long.parseLong(text(i.getArgument(2),"dispute_id")),"outcome","NEW"));}
    com.oms.messaging.MessageHandler.Outcome step(long id){ExchangePullMessage h=new ExchangePullMessage();h.sync=sync;return h.handle("VERIFY",map("business_id",id,"business_version",1));}
    void drain(long id){for(int i=0;i<25;i++){com.oms.messaging.MessageHandler.Outcome result=step(id);if(!result.progress||"COMPLETED".equals(sync.task("VERIFY",id).get("state")))return;}throw new AssertionError("Task did not finish");}
    @AfterEach void close(){sync.close();}
    long submit(String ids,String key){return number(sync.submit("VERIFY",map("channel_id",1,"dispute_ids",ids,"request_key",key),"test"),"id");}
    void response(String id){when(exchange.call(eq("VERIFY"),eq(1L),eq("DETAIL"),argThat(m->m!=null&&id.equals(m.get("dispute_id"))))).thenReturn(map("exchange",map("dispute_id",id)));}
    @Test void idsAreReadOnlyDurableAndDuplicateSubmissionIsIdempotent(){response("9001");response("9002");long task=submit("9001,9002","request_001");assertEquals(task,submit("9001,9002","request_001"));String cursor=db.query("SELECT cursor_time FROM oms_exchange_config",ROW).get(0).get("cursor_time").toString();drain(task);Map<String,Object> t=sync.task("VERIFY",task);assertEquals("COMPLETED",t.get("state"));assertEquals(2,number(t,"new_count"));assertEquals(2,((List<?>)t.get("items")).size());assertEquals(cursor,db.query("SELECT cursor_time FROM oms_exchange_config",ROW).get(0).get("cursor_time"));verify(exchange,times(2)).call(eq("VERIFY"),eq(1L),eq("DETAIL"),anyMap());assertThrows(IllegalArgumentException.class,()->sync.task("OTHER",task));assertThrows(IllegalArgumentException.class,()->sync.retry("OTHER",task));}
    @Test void partialFailureRetainsSuccessAndRetryQueriesOnlyFailedApplication(){response("9001");when(exchange.call(eq("VERIFY"),eq(1L),eq("DETAIL"),argThat(m->m!=null&&"9002".equals(m.get("dispute_id"))))).thenThrow(new IllegalArgumentException("申请暂不可读"));long task=submit("9001,9002","request_002");drain(task);Map<String,Object> t=sync.task("VERIFY",task);assertEquals("RUNNING",t.get("state"));assertEquals(1,number(t,"new_count"));assertEquals(1,number(t,"failed_count"));response("9002");drain(task);t=sync.task("VERIFY",task);assertEquals("COMPLETED",t.get("state"));assertEquals(2,number(t,"new_count"));assertEquals(0,number(t,"failed_count"));verify(exchange,times(1)).call(eq("VERIFY"),eq(1L),eq("DETAIL"),argThat(m->m!=null&&"9001".equals(m.get("dispute_id"))));}
    @Test void sameRequestKeyCannotBeUsedForAnotherScope(){submit("9001","request_003");assertThrows(IllegalArgumentException.class,()->submit("9002","request_003"));}
    @Test void timeValidationRejectsEqualityAndMoreThan31Days(){for(String end:Arrays.asList("2026-09-01 00:00:00","2026-10-02 00:00:01"))assertThrows(IllegalArgumentException.class,()->sync.submit("VERIFY",map("channel_id",1,"request_key","request_004","start_time","2026-09-01 00:00:00","end_time",end),"test"));}
    @Test void exhaustedAutomaticWindowCannotBeRecreatedAsANewTask(){submit("9001","request_006");db.update("UPDATE oms_exchange_config SET enabled=1,initial_time='2026-10-01 00:00:00',cursor_time='2026-10-01 00:00:00'");db.update("UPDATE oms_exchange_sync SET mode='AUTO',state='FAILED',start_time='2026-10-01 00:00:00',end_time='2026-10-02 00:00:00'");sync.shop("VERIFY",1);assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_exchange_sync",Integer.class));verify(exchange,never()).call(anyString(),anyLong(),anyString(),anyMap());}
    @Test void scannerDoesNotCallPlatformOrConsumeFailedTask(){long task=submit("9001","request_005");sync.shop("VERIFY",1);assertEquals("PENDING",sync.task("VERIFY",task).get("state"));db.update("UPDATE oms_exchange_sync SET state='FAILED'");sync.shop("VERIFY",1);verify(exchange,never()).call(anyString(),anyLong(),anyString(),anyMap());}
    @Test void requestDuringActiveScanSchedulesAnotherPass(){
        com.baomidou.dynamic.datasource.DynamicRoutingDataSource ds=mock(com.baomidou.dynamic.datasource.DynamicRoutingDataSource.class);javax.sql.DataSource pool=mock(javax.sql.DataSource.class);when(ds.getDataSources()).thenReturn(Collections.singletonMap("master",pool));when(ds.getGroupDataSources()).thenReturn(Collections.emptyMap());when(ds.getDataSource("master")).thenReturn(pool);
        com.oms.common.tenant.TenantRouting tenants=new com.oms.common.tenant.TenantRouting();tenants.setRoutes(Collections.singletonMap("VERIFY","master"));ReflectionTestUtils.setField(tenants,"dataSource",ds);
        com.oms.common.task.ScopedWorkExecutor executor=mock(com.oms.common.task.ScopedWorkExecutor.class);List<Runnable> queued=new ArrayList<>();when(executor.submit(any(),any())).thenAnswer(a->{queued.add(a.getArgument(1));return true;});ReflectionTestUtils.setField(sync,"tenants",tenants);ReflectionTestUtils.setField(sync,"executor",executor);sync=spy(sync);java.util.concurrent.atomic.AtomicInteger runs=new java.util.concurrent.atomic.AtomicInteger();doAnswer(a->{if(runs.incrementAndGet()==1)assertFalse(sync.kick("VERIFY"));return null;}).when(sync).run("VERIFY");
        assertTrue(sync.kick("VERIFY"));queued.get(0).run();assertEquals(2,queued.size());queued.get(1).run();assertEquals(2,runs.get());assertEquals(2,queued.size());
    }

}
